// Hammered Copper - color. STATIC (no t/u_time). Runs INSIDE shadeSurface().
// Polished metal is mostly REFLECTION: the dents (real normals, from the relief)
// mirror a simple warm sky / dark ground environment, so each dent catches a
// highlight on one side and a shadow on the other. Verdigris collects along the
// ridges and in a few patches.
// In scope: pModel, n_model, viewDir_model, mainLight_model.
// Dock colors: u_col1 = bright copper, u_col2 = dark copper / shadow.

float DENSITY  = 16.0 * max(E, 0.05);  // slider E   // MUST match the displacement
float JITTER   = 0.9;
float SHINE    = 0.9;   // strength of the sharp highlight            [0 .. 2]
float VERDIGRIS = 0.55; // amount of green patina                      [0 .. 1]
vec3  PATINA   = vec3(0.30, 0.62, 0.52);   // verdigris color

// --- SAME Voronoi as the displacement: F1 tells ridge from dent bottom.
vec3 vp = pModel * DENSITY;
vec3 vi = floor(vp);
vec3 vf = fract(vp);
float d1 = 8.0;
for (int gx = -1; gx <= 1; gx++)
for (int gy = -1; gy <= 1; gy++)
for (int gz = -1; gz <= 1; gz++) {
    vec3 g = vec3(float(gx), float(gy), float(gz));
    vec3 h3 = fract((vi + g) * vec3(0.1031, 0.1030, 0.0973));
    h3 += dot(h3, h3.yxz + 33.33);
    vec3 o = 0.5 + JITTER * (fract((h3.xxy + h3.yxx) * h3.zyx) - 0.5);
    vec3 r = g + o - vf;
    d1 = min(d1, dot(r, r));
}
float ridge = smoothstep(0.25, 0.45, d1);   // 1 on the ridges between dents

// --- patina patches: 2 octaves of value noise
vec3 np = pModel * 3.0;
float pn = 0.0;
float pa = 0.6;
for (int oct = 0; oct < 2; oct++) {
    vec3 ip = floor(np);
    vec3 fr = fract(np);
    vec3 w  = fr * fr * (3.0 - 2.0 * fr);
    float h000 = fract(sin(dot(ip + vec3(0.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h100 = fract(sin(dot(ip + vec3(1.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h010 = fract(sin(dot(ip + vec3(0.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h110 = fract(sin(dot(ip + vec3(1.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h001 = fract(sin(dot(ip + vec3(0.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h101 = fract(sin(dot(ip + vec3(1.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h011 = fract(sin(dot(ip + vec3(0.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h111 = fract(sin(dot(ip + vec3(1.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float z0 = mix(mix(h000, h100, w.x), mix(h010, h110, w.x), w.y);
    float z1 = mix(mix(h001, h101, w.x), mix(h011, h111, w.x), w.y);
    pn += pa * mix(z0, z1, w.z);
    np *= 2.1;
    pa *= 0.4;
}
pn /= 0.84;

// --- environment reflection: warm sky above, dark ground below
vec3 R = reflect(-viewDir_model, n_model);
float sky = smoothstep(-0.35, 0.65, R.y);
vec3 metal = mix(ubuf.u_col2 * 0.8, ubuf.u_col1 * 1.15, sky);
// sharp highlight of the main light, independent of the Specular toggle
metal += ubuf.u_col1 * SHINE * pow(max(dot(R, mainLight_model), 0.0), 48.0);
// grazing angles reflect more (Fresnel)
float fres = pow(1.0 - max(dot(n_model, viewDir_model), 0.0), 4.0);
metal = mix(metal, ubuf.u_col1 * 1.3, fres * 0.35);

// --- verdigris on the ridges, more where the patch noise is high
float verd = VERDIGRIS * ridge * smoothstep(0.45, 0.75, pn);
verd = max(verd, VERDIGRIS * 0.8 * smoothstep(0.68, 0.80, pn));
metal = mix(metal, PATINA * (0.75 + 0.25 * pn), clamp(verd, 0.0, 1.0));

textureCol = metal;

