// Hammered Copper - relief (displacement). STATIC (no t/u_time). Runs INSIDE map().
// Beaten metal: every hammer blow leaves a shallow round dent, and the dents meet
// in sharp ridges. Each cell of a 3D Voronoi is a dent shaped like a paraboloid
// around the cell point (F1^2): deepest at the point, highest on the borders.
// In scope: d_surf, p, pModel.  Convention: d_surf += depth -> pushed inward.
//
// SPEED. The dents are a few thousandths deep, so they only matter close to the
// surface: the 27-cell Voronoi runs inside a BAND around it and the dent depth is
// faded to zero at the edge of the band (smooth, the field stays continuous).
// Far from the surface -- where a missed ray spends ~100 steps -- this costs one
// smoothstep. The cell points come from an arithmetic hash (no sin()).

float DENSITY = 16.0 * max(E, 0.05);  // slider E   // dents per unit          [8 .. 40]
float DENT    = 0.016 * max(F, 0.0);  // slider F   // dent depth (field)      [0 .. 0.04]
float JITTER  = 0.9;    // 0 = regular grid of dents, 1 = fully random       [0.5 .. 1.0]

float BAND   = max(0.3, 15.0 * DENT);
float inBand = 1.0 - smoothstep(0.5 * BAND, BAND, abs(d_surf));

if (inBand > 0.0) {
    vec3 vp = pModel * DENSITY;
    vec3 vi = floor(vp);
    vec3 vf = fract(vp);

    float d1 = 8.0;   // squared distance to the nearest cell point
    for (int gx = -1; gx <= 1; gx++)
    for (int gy = -1; gy <= 1; gy++)
    for (int gz = -1; gz <= 1; gz++) {
        vec3 g = vec3(float(gx), float(gy), float(gz));
        vec3 h3 = fract((vi + g) * vec3(0.1031, 0.1030, 0.0973));
        h3 += dot(h3, h3.yxz + 33.33);
        vec3 o = 0.5 + JITTER * (fract((h3.xxy + h3.yxx) * h3.zyx) - 0.5);
        vec3 r = g + o - vf;
        d1 = min(d1, dot(r, r));
    }

    // paraboloid dent: 1 at the cell point, 0 where the dents meet (F1^2 ~ 0.45)
    float dent = 1.0 - min(d1 / 0.45, 1.0);

    d_surf += DENT * dent * inBand;
}
